@dataclass
class PageText:
    page_number: int
    text: str
    method: str
    ocr_note: str = NOT_PROVIDED
    layout_note: str = NOT_PROVIDED

@dataclass
class TextUnit:
    page_number: int
    text: str
    is_bold: bool = False
    is_italic: bool = False
    zone_flags: str = ""   # "systematic", "references", "synonymy", "caption", …
    bbox: Optional[Tuple[float,float,float,float]] = None


@dataclass
class OperationResult:
    """Testable service-layer result independent of Streamlit widgets."""
    ok: bool
    message: str = ""
    error_code: str = ""
    details: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DocumentIndexResult(OperationResult):
    document_id: Optional[int] = None
    stored_path: Optional[pathlib.Path] = None
    pages: List[PageText] = field(default_factory=list)
    diagnostics: Dict[str, Any] = field(default_factory=dict)
    char_count: int = 0


