def _lang_code_to_name(code: str) -> str:
    """Vrátí anglický název jazyka pro zadaný kód (ISO 639-1/2).
    Pro 'mixed', '' nebo neznámý kód vrátí 'auto-detect'."""
    c = (code or "").strip().lower()
    if not c or c == "mixed":
        return "auto-detect"
    return _LANG_NAMES.get(c, c.upper())

